def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        match = re.search(r"<([^<>]*)>", value)
        email = (match.group(1) if match else value).strip().lower()

        if email.count("@") != 1:
            return ""

        local, domain = email.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if not local or "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""
        return f"{local}@{domain}"

    def normalize_phone(value):
        value = re.split(r"ext|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"[^0-9]", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        return digits if len(digits) == 10 and digits[0] not in "01" else ""

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"[0-9]{5}-[0-9]{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"[0-9]{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"[0-9]{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        return value.title() if value.isupper() or value.islower() else value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Unsupported updated value: {value!r}")

    # Normalize and discard unreachable contacts before matching.
    contacts = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        contacts.append({
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            },
            "opted_out": row["opted_out"].strip().lower() in {
                "y", "yes", "true", "1"
            },
            "_updated": parse_updated(row["updated"]),
            "_index": index,
        })

    # Union-find captures transitive matches.
    parent = list(range(len(contacts)))
    size = [1] * len(contacts)

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        a, b = find(a), find(b)
        if a == b:
            return
        if size[a] < size[b]:
            a, b = b, a
        parent[b] = a
        size[a] += size[b]

    email_owner = {}
    phone_name_owner = {}

    for i, contact in enumerate(contacts):
        email = contact["email"]
        if email:
            if email in email_owner:
                union(i, email_owner[email])
            else:
                email_owner[email] = i

        if contact["phone"] and contact["last_name"]:
            key = (contact["phone"], contact["last_name"].casefold())
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, contact in enumerate(contacts):
        groups.setdefault(find(i), []).append(contact)

    def preference(contact):
        return (
            contact["source"] == "manual",
            contact["_updated"],
            -contact["_index"],
        )

    result = []
    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(contact["_index"] for contact in group),
    )

    for group in ordered_groups:
        person = {}
        for field in ("first_name", "last_name", "zip", "email", "phone", "source"):
            winner = max(
                (contact for contact in group if contact[field]),
                key=preference,
                default=None,
            )
            person[field] = winner[field] if winner is not None else ""

        person["tags"] = ";".join(sorted({
            tag for contact in group for tag in contact["tags"]
        }))
        person["opted_out"] = "Y" if any(
            contact["opted_out"] for contact in group
        ) else "N"
        person["updated"] = max(
            contact["_updated"] for contact in group
        ).date().isoformat()
        result.append(person)

    return result
